from typing import Optional

from taf.nms.netact.ssh_node import SshNode


class Keycloak:
    """
    The keycloak_user_mgmt.sh is available since NetAct20,
    so this functionality is supported since then as well.
    """
    SCRIPT_PATH = r'/opt/oss/Nokia-sm_keycloak-service-handler/install/bin/keycloak_user_mgmt.sh'

    def __init__(self) -> None:
        self._password: Optional[str] = None

    def password(self,
                 node: SshNode,
                 admin_user: str,
                 realm_name: str
                 ) -> str:
        if self._password is None:
            self._password = self.get_password(
                node, admin_user, realm_name
            )
        return self._password

    def get_password(self,
                     node: SshNode,
                     admin_user: str,
                     realm_name: str
                     ) -> str:
        script_args = f"--get --realm {realm_name} --user {admin_user}"
        command = f"{self.SCRIPT_PATH} {script_args}"
        with node as connected_node:
            return connected_node.execute_command(command).stdout
